// Parses the output of "df -P", compares it against tiered thresholds (WARN/CRIT)
// and only reports when a mountpoint CHANGES level. The de-duplication uses n8n's
// workflow static data, so a disk sitting at 85% for a week alerts once, not 336 times.
// Thresholds are read from environment variables so the workflow needs no editing.
const warnPct = parseInt($env.DISK_WARN_PCT || '80', 10);
const critPct = parseInt($env.DISK_CRIT_PCT || '90', 10);

const raw = $input.first().json.stdout || '';
const lines = raw.trim().split('\n').slice(1);

const staticData = $getWorkflowStaticData('node');
if (!staticData.lastLevel) staticData.lastLevel = {};

const alerts = [];
for (const line of lines) {
  const parts = line.trim().split(/\s+/);
  if (parts.length < 6) continue;
  const filesystem = parts[0];
  const capacityStr = parts[parts.length - 2];
  const mount = parts[parts.length - 1];
  const usedPct = parseInt(capacityStr.replace('%', ''), 10);
  if (Number.isNaN(usedPct)) continue;

  let level = 'ok';
  if (usedPct >= critPct) level = 'critical';
  else if (usedPct >= warnPct) level = 'warning';

  const prevLevel = staticData.lastLevel[mount] || 'ok';
  if (level !== prevLevel) {
    staticData.lastLevel[mount] = level;
    const availGB = (parseInt(parts[parts.length - 3], 10) / 1024 / 1024).toFixed(1);
    if (level !== 'ok') {
      alerts.push({ mount, filesystem, usedPct, level, availGB });
    } else {
      // Recovery is reported too, so a silent channel means "nothing changed",
      // not "the workflow died".
      alerts.push({ mount, filesystem, usedPct, level, availGB, recovered: true });
    }
  }
}

const hasAlerts = alerts.length > 0;
let message = null;
if (hasAlerts) {
  message = alerts.map(a => a.recovered
    ? `[OK] ${a.mount} back below threshold (${a.usedPct}%)`
    : `${a.level === 'critical' ? '[CRITICAL]' : '[WARNING]'} ${a.mount} (${a.filesystem}): ${a.usedPct}% used, ${a.availGB} GB free`
  ).join('\n');
}

return [{ json: { hasAlerts, message, alerts } }];
